const CMB=q=>{if(!q.o||!q.o.every(x=>/^[ㄱ-ㅎ](, [ㄱ-ㅎ])*$/.test(x)))return q;const ans=q.o[q.a];const o=[...q.o].sort((a,b)=>a.length-b.length||(a<b?-1:a>b?1:0));q.o=o;q.a=o.indexOf(ans);return q};
Object.values(ETQ).forEach(L=>L.forEach(CMB));Object.values(ETMK).forEach(L=>L.forEach(CMB));
CUR[ETN]=UN.map((n,u)=>({n,m:MN[u].map((nm,k)=>{const pre='eth'+(u+2)+(k+1);return {n:nm,q:(ETQ[u+'-'+k]||[]).map((q,i)=>Object.assign({id:pre+(q.lv?'x':'b')+String(i+1).padStart(2,'0')},q))}})}));
const R5=[[],[],[],[],[]];let j=0;
MN.forEach((L,u)=>L.forEach((_,k)=>(ETMK[u+'-'+k]||[]).forEach(q=>{R5[j%5].push({o:u*10+k,q});j++})));
MOCK[ETN]=R5.map((L,r)=>({n:(r+1)+'회',q:L.sort((a,b)=>a.o-b.o).map((x,i)=>Object.assign({id:'ethm'+(r+1)+String(i+1).padStart(2,'0'),mk:1,t:'mc'},x.q))}));
